\item[S2] Sebastian Endres and Frank Steiner, \emph{The Berry--Keating operator on $L^2(\mathbb R_{>},dx)$ and on compact quantum graphs with general self-adjoint realizations}, arXiv:0912.3183v5 (2011), Section 1, pp. 2--3. \url{https://arxiv.org/pdf/0912.3183}.
